def compute(vars):
    start_balance = vars["v1"]
    end_balance = vars["v2"]
    change = end_balance - start_balance

    return {
        "value": change,
        "trace": {
            "start_balance": start_balance,
            "end_balance": end_balance,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            },
            "notes": "Source reporting scale is unknown, so the requested conversion to millions is unsupported; the reported-scale difference is preserved."
        }
    }
